#!/usr/bin/env node
// Bundles lib/game/goal-rush.html into a TS string module so the game can be
// loaded inline (WebView `source={{ html }}` on native, iframe `srcDoc` on web).
// Run after editing the HTML:  npm run build:game
const fs = require('fs')
const path = require('path')

const src = path.join(__dirname, '..', 'lib', 'game', 'goal-rush.html')
const out = path.join(__dirname, '..', 'lib', 'game', 'goalRushHtml.ts')

const html = fs.readFileSync(src, 'utf8')
const body =
  '// AUTO-GENERATED by scripts/build-game.js from goal-rush.html — do not edit by hand.\n' +
  'export const GOAL_RUSH_HTML: string = ' + JSON.stringify(html) + '\n'

fs.writeFileSync(out, body)
console.log('Wrote ' + path.relative(process.cwd(), out) + ' (' + html.length + ' chars)')
